/**
 * The authored AZ-802 bank. The fields used today are required; the enrichment
 * fields are optional so the bank can be completed domain by domain without
 * changing a single question ID, progress row, or audit manifest entry.
 */
export type Question = {
  id: string;
  domain: string;
  text: string;
  options: string[];
  correct: number;
  source: string;
  rationale: { fa: string; en: string; de: string };
  skillId: string;
  reviewStatus: string;
  isOriginal: boolean;
  textFa: string;
  optionsFa: string[];
  audit: {
    sourceRefs: string[];
    sourceVerified: boolean;
    answerVerified: boolean;
    originalityVerified: boolean;
    translationVerified: boolean;
    distractorsReviewed: boolean;
    reviewer: string | null;
    reviewedAt: string | null;
  };
  /** Verbatim bullet from the official AZ-802 study guide that this item assesses. */
  objective?: string;
  /** Stable local slug for grouping and filters; not an official Microsoft objective number. */
  objectiveId?: string;
  /** Short topic label used by the domain -> topic -> question tree. */
  topic?: string;
  /** One of "easy", "medium", "hard". The bank is authored one JSON object per
   * line, so array-literal widening prevents a compile-time union here; both
   * scripts/validate-question-bank.mjs and scripts/validate-az802-coverage.mjs
   * enforce the allowed values. */
  difficulty?: string;
  /** Page-specific Microsoft Learn references that prove the answer. */
  sourceRefs?: string[];
  /** Scenario facts that determine the correct answer. */
  keyPoints?: string[];
  /** Index-aligned reasoning for every option; empty string at the correct index. */
  whyOthers?: string[];
  /** Windows Server version, prerequisites, or effective limits that change the answer. */
  requirements?: string;
  /** A real command or settings path; only where it genuinely clarifies the answer. */
  commandPath?: { label: string; command: string }[];
  /** Set to "runtime-google" when display translations come from the site's
   * existing Google Translate flow instead of stored Persian fields. Widened to
   * string for the same array-literal reason as difficulty; the validators
   * accept only the documented value. */
  translations?: string;
};

export const questions: Question[] = questionBank;











